    faqs: [{ q: "How many custom product pages can an app create?", a: "Apple currently states that an app can publish up to 70 additional custom product pages." }, { q: "Can custom product pages appear in App Store search?", a: "Yes. Apple allows approved pages to be made visible for assigned keywords, subject to current configuration and availability." }],
